(()=>{'use strict';
 // One companion above the whole site, including its instant-navigation frames.
 if(window.top!==window||document.getElementById('day-animal'))return;
 const animals=[
  ['penguin',`<path fill="#e9a940" d="M16 46h10l3 4H15zm18 0h10l3 4H33z" class="animal-feet"/><path fill="#283742" d="M15 40c-3-7-1-18 4-24 2-12 20-14 26-2 4 8 1 15-1 20l-1 11c-10 7-25 5-28-5Z"/><path fill="#f4f5ed" d="M24 20c2-7 12-9 16-2 5 8 2 21-2 25-6 5-18 0-17-7Z"/><path fill="#24323c" d="M20 24c-9 1-13 10-9 15 5-1 11-7 12-11Z"/><path fill="#edb052" d="m42 17 10 4-11 4Z"/><circle cx="38" cy="15" r="2.1" fill="#11181b"/><circle cx="38.6" cy="14.4" r=".6" fill="white"/>`],
  ['red panda',`<path fill="none" stroke="#a95331" stroke-width="10" stroke-linecap="round" d="M23 34C9 40 4 28 8 21"/><path fill="none" stroke="#e7a965" stroke-width="4" d="m7 25 6-2m-5 9 6-3m1 10 3-7"/><g class="animal-feet" fill="#493229"><path d="m24 34-2 14h8l2-14zm13 0 1 14h8l-3-15Z"/></g><ellipse cx="31" cy="32" rx="16" ry="11" fill="#b9663c"/><path fill="#a94e2d" d="m34 19-2-13 10 6 9-6 3 15Z"/><ellipse cx="43" cy="22" rx="13" ry="12" fill="#cc7845"/><path fill="#f2e4ce" d="m32 19 6-4 4 6 8-6 5 5-5 10-9 3-8-7Z"/><path fill="#6b3c2a" d="m34 21 5-2 2 5-5 1zm12 0 5-2 1 5-5 1Z"/><circle cx="39" cy="22" r="1.6"/><circle cx="49" cy="22" r="1.6"/><path fill="#352924" d="m45 26 5 1-3 3Z"/>`],
  ['arctic fox',`<path fill="#d4dee4" d="M23 33C12 19 3 29 5 38c4 7 14 8 22 2Z"/><path fill="#faf9ef" d="M13 26c-5-1-9 5-7 10l7-1Z"/><g class="animal-feet" fill="#d5dfe5"><path d="m24 34-2 14h8l1-14zm13 0 2 14h8l-5-15Z"/></g><ellipse cx="31" cy="32" rx="15" ry="11" fill="#edf1ec"/><path fill="#edf1ec" d="m32 23 1-17 10 10 7-10 4 17 5 7-13 8-16-7Z"/><path fill="#c6d1d9" d="m36 13 1 9 5-2zm13 0-4 8 6 1Z"/><path fill="#fffdf4" d="m37 27 17-2 6 5-14 7Z"/><circle cx="48" cy="24" r="1.7" fill="#1f303a"/><path fill="#25343b" d="m56 28 5 1-3 3Z"/>`],
  ['baby harp seal',`<ellipse cx="29" cy="38" rx="24" ry="11" fill="#e7ece9"/><path fill="#cbd7da" d="M11 37 2 31l1 13 12 1Z"/><ellipse cx="43" cy="29" rx="14" ry="13" fill="#f5f4ec"/><path class="animal-flipper" fill="#cbd8db" d="M29 37c-7 1-10 8-7 12 5 0 11-6 12-10Z"/><ellipse cx="49" cy="28" rx="2.7" ry="3.1" fill="#26363e"/><circle cx="49.8" cy="27" r=".8" fill="white"/><ellipse cx="55" cy="34" rx="3" ry="2" fill="#57646a"/><path fill="none" stroke="#9ca9ad" stroke-width=".8" d="m53 35 9-2m-9 3 9 2m-10-1-6 3"/>`],
  ['tiny owl',`<path class="animal-feet" fill="#cba36a" d="m24 44-3 5h10l-3-5zm13 0-3 5h10l-3-5Z"/><path fill="#8b7563" d="M17 36c-3-6-2-17 0-22L15 5l12 6c5-2 10-1 13 0l11-6-2 13c7 12 1 27-12 29-13 2-20-3-20-11Z"/><path fill="#d4c1a0" d="M19 21c0-10 13-12 16-3 5-8 16-4 15 4-1 9-11 13-15 9-5 5-16-1-16-10Z"/><ellipse cx="28" cy="22" rx="4" ry="5" fill="#342f2c"/><ellipse cx="43" cy="22" rx="4" ry="5" fill="#342f2c"/><circle cx="29" cy="20" r="1.1" fill="#fff8e7"/><circle cx="44" cy="20" r="1.1" fill="#fff8e7"/><path fill="#d9ad60" d="m33 27 6 0-3 5Z"/><path fill="#6d5b50" d="M18 28c-5 1-4 12 5 15l6-5Z"/><path fill="none" stroke="#bca58a" stroke-width="2" d="m32 37 3 2 3-2m-5 6 3 1 3-2"/>`]
 ];
 const companion=document.createElement('div');companion.id='day-animal';companion.setAttribute('aria-hidden','true');document.body.append(companion);
 let lastDay='';
 function update(){const now=new Date(),day=[now.getFullYear(),now.getMonth(),now.getDate()].join('-');if(day!==lastDay){lastDay=day;const ordinal=Math.floor(Date.UTC(now.getFullYear(),now.getMonth(),now.getDate())/86400000),[name,art]=animals[((ordinal%animals.length)+animals.length)%animals.length];companion.dataset.animal=name;companion.innerHTML='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 54"><ellipse cx="32" cy="50" rx="23" ry="2" fill="#000" opacity=".16"/><g class="animal-body">'+art+'</g></svg>';}
 const fraction=(now.getHours()*3600+now.getMinutes()*60+now.getSeconds())/86400;companion.style.left=Math.max(0,(document.documentElement.clientWidth-companion.getBoundingClientRect().width)*fraction)+'px';companion.classList.toggle('animal-paused',document.hidden);}
 update();setInterval(()=>{if(!document.hidden)update();},30000);window.addEventListener('resize',update);window.addEventListener('pageshow',update);document.addEventListener('visibilitychange',update);
})();
